package plugin

import (
	"encoding/json"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// The 0.28 compatibility guarantee: a schema-1 manifest and a tree that
// validated under 0.28 give the same fields, the same problems and the same
// tree digest on every later version. testdata/schema1/golden.json was
// generated by the v0.28.0 code from this very test file (COMPAT_WRITE=<path>
// go test -run TestSchema1Compat in a v0.28.0 worktree); it must never be
// regenerated from a newer build. The digest is what every approval ever made
// is pinned to.

type compatManifest struct {
	Schema       *int
	Name         string
	Version      string
	DisplayName  string
	Description  string
	Cartographer string
	Depends      map[string]string
	Permissions  *Permissions
	Settings     map[string]Setting
}

type compatResult struct {
	Manifest *compatManifest `json:",omitempty"`
	Problems []string
	Digest   string `json:",omitempty"`
	Files    int    `json:",omitempty"`
}

var compatOpts = Options{
	RunningVersion: "0.29.0",
	ReservedName:   func(n string) bool { return n == "sync" || n == "plugin" },
}

const compatBase = "schema: 1\nname: team-forks\nversion: 1.2.3\ndisplay_name: Team forks\ndescription: Closed forks.\ncartographer: \">=0.28.0\"\n"

// compatManifests are the manifests read on their own; the problem cases are
// those of TestParseManifestProblems that are about the shape of the file.
var compatManifests = map[string]string{
	"base":        compatBase,
	"pin-0.28":    strings.Replace(compatBase, ">=0.28.0", ">=0.28.0 <0.29.0", 1) + "permissions:\n  net: [a.example.com, \"*.example.com\"]\n  env: [FORK_TOKEN]\n  files:\n    read: [\"{home}/.fork/*.json\"]\n    write: [\"{xdg_config}/fork/state\"]\nsettings:\n  retries:\n    type: int\n    default: 3\n    description: How many times.\n",
	"full":        compatBase + "depends:\n  base-skills: \">=1.0.0\"\npermissions:\n  kb: read\n  net: [gitlab.example.com]\n  env: [LANG]\nsettings:\n  endpoint:\n    type: string\n    default: https://example.com\n    description: Where.\n",
	"empty":       "",
	"unknown":     compatBase + "colour: red\n",
	"nested":      compatBase + "permissions:\n  disk: all\n",
	"alias":       compatBase + "x: &a 1\ny: *a\n",
	"two docs":    compatBase + "---\nschema: 1\n",
	"not yaml":    "schema: [",
	"no schema":   strings.Replace(compatBase, "schema: 1\n", "", 1),
	"schema 3":    strings.Replace(compatBase, "schema: 1", "schema: 3", 1),
	"schema 0":    strings.Replace(compatBase, "schema: 1", "schema: 0", 1),
	"bad name":    strings.Replace(compatBase, "team-forks", "Team", 1),
	"reserved":    strings.Replace(compatBase, "team-forks", "sync", 1),
	"bad range":   strings.Replace(compatBase, ">=0.28.0", "~0.28", 1),
	"net scheme":  compatBase + "permissions:\n  net: [\"https://example.com\"]\n",
	"env reserve": compatBase + "permissions:\n  env: [PATH]\n",
	"files abs":   compatBase + "permissions:\n  files:\n    read: [\"/etc/passwd\"]\n",
	"setting":     compatBase + "settings:\n  Bad:\n    type: string\n    description: x\n",
}

func compatTrees(t *testing.T) map[string][]TreeFile {
	t.Helper()
	out := map[string][]TreeFile{}
	root := filepath.Join("testdata", "schema1", "trees")
	entries, err := os.ReadDir(root)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		var files []TreeFile
		base := filepath.Join(root, e.Name())
		err := filepath.WalkDir(base, func(p string, d fs.DirEntry, err error) error {
			if err != nil || d.IsDir() {
				return err
			}
			data, err := os.ReadFile(p)
			if err != nil {
				return err
			}
			rel, _ := filepath.Rel(base, p)
			files = append(files, TreeFile{Path: filepath.ToSlash(rel), Content: data})
			return nil
		})
		if err != nil {
			t.Fatal(err)
		}
		out[e.Name()] = files
	}
	return out
}

func compatResults(t *testing.T) map[string]compatResult {
	t.Helper()
	res := map[string]compatResult{}
	for name, in := range compatManifests {
		m, probs := ParseManifest([]byte(in), compatOpts)
		r := compatResult{Problems: probs}
		if len(probs) == 0 {
			r.Manifest = &compatManifest{m.Schema, m.Name, m.Version, m.DisplayName, m.Description, m.Cartographer, m.Depends, m.Permissions, m.Settings}
		}
		res["manifest/"+name] = r
	}
	for name, files := range compatTrees(t) {
		p, probs := ReadTree(files, compatOpts)
		res["tree/"+name] = compatResult{Problems: probs, Digest: p.Digest, Files: len(p.Files)}
	}
	return res
}

func TestSchema1Compat(t *testing.T) {
	got := compatResults(t)
	if path := os.Getenv("COMPAT_WRITE"); path != "" {
		data, _ := json.MarshalIndent(got, "", "  ")
		if err := os.WriteFile(path, append(data, '\n'), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	data, err := os.ReadFile(filepath.Join("testdata", "schema1", "golden.json"))
	if err != nil {
		t.Fatal(err)
	}
	var want map[string]compatResult
	if err := json.Unmarshal(data, &want); err != nil {
		t.Fatal(err)
	}
	if len(got) != len(want) {
		t.Errorf("%d cases, golden has %d", len(got), len(want))
	}
	for name, w := range want {
		g, ok := got[name]
		if !ok {
			t.Errorf("%s: no result", name)
			continue
		}
		// Problems of a golden with none read back as nil.
		if len(g.Problems) == 0 && len(w.Problems) == 0 {
			g.Problems, w.Problems = nil, nil
		}
		if !reflect.DeepEqual(g, w) {
			t.Errorf("%s differs from the v0.28.0 golden:\n got %+v\nwant %+v", name, g, w)
		}
	}
}
